async def act(page):
    # First, try to locate a 'Categories' section using get_by_role with name 'Categories'
    categories_section = None

    # Try to find by role 'region' with name 'Categories'
    try:
        categories_section = page.get_by_role('region', name='Categories', exact=False)
        await categories_section.wait_for(state='visible', timeout=2000)
    except:
        try:
            # If not found, try role 'group' with name 'Categories'
            categories_section = page.get_by_role('group', name='Categories', exact=False)
            await categories_section.wait_for(state='visible', timeout=2000)
        except:
            categories_section = None

    if categories_section:
        # Find all links within the categories section using get_by_role
        links = categories_section.get_by_role('link')
        count = await links.count()
        if count >= 3:
            # Click the third link (index 2)
            await links.nth(2).click()
            await page.wait_for_load_state('networkidle')
            return 'Clicked the third link in the Categories section.'
        else:
            return f'Found Categories section but only {count} links, need at least 3.'
    else:
        # If no Categories section found by role, look for any element with text 'Categories'
        try:
            categories_element = page.get_by_text('Categories', exact=False)
            await categories_element.wait_for(state='visible', timeout=2000)
            # Use get_by_role to find a parent element; assume it's a 'region' or 'group'
            # Since we can't use CSS selectors, try to get the parent via accessibility tree
            # We'll use filter to find a region or group that contains the text
            parent_region = page.get_by_role('region').filter(has=categories_element)
            parent_group = page.get_by_role('group').filter(has=categories_element)
            # Check which one is visible
            try:
                await parent_region.wait_for(state='visible', timeout=1000)
                parent = parent_region
            except:
                try:
                    await parent_group.wait_for(state='visible', timeout=1000)
                    parent = parent_group
                except:
                    parent = None

            if parent:
                links_in_parent = parent.get_by_role('link')
                count = await links_in_parent.count()
                if count >= 3:
                    await links_in_parent.nth(2).click()
                    await page.wait_for_load_state('networkidle')
                    return 'Clicked the third link near Categories text.'
                else:
                    return f'Found Categories text but only {count} links nearby.'
            else:
                return 'Could not find parent element for Categories text.'
        except:
            return 'Could not find Categories section or text on the page.'

